from cosmo_wap.bk import WS_ as _ws
from cosmo_wap.bk_mt.GR1 import GR1 as _GR1
from cosmo_wap.bk_mt.GR2 import GR2 as _GR2
from cosmo_wap.lib.utils import composite as _composite

############################################################### wide separation terms
# three tracers and any LOS, from their angle-dependent forms in bk/WS_.py (generated by mathwap): ylm (so FoG) and
# every lx/lxmy up to l4, by projecting the mu1^a mu2^b coefficients exactly
WA1, WA2, WARR, RR1, RR2, WAGR, RRGR = (_ws._multipole_class(n) for n in ('WA1', 'WA2', 'WARR', 'RR1', 'RR2', 'WAGR', 'RRGR'))


############################################################### composite terms
_WS = [(WA1, 1), (RR1, 1), (WA2, 0), (WARR, 0), (RR2, 0)]
# GR1 and GR2 have no ylm or m > 0, and GR2.l4 is only a stand-in, so Full stops at l3 with m = 0 - see lib.utils.composite
WS = _composite("WS", "Pure wide separation terms, RR + WA", _WS, bk=True, module=__name__)
WSGR = _composite("WSGR", "Full wide separation effects including relativistic mixing", _WS + [(WAGR, 0), (RRGR, 0)],
                  bk=True, module=__name__)
Full = _composite("Full", "WS + GR", _WS + [(WAGR, 0), (RRGR, 0), (_GR1, 1), (_GR2, 0)], bk=True, module=__name__)
